        // succeeds for ANY fuzzed keeper address and keeper() reflects it.
        vm.prank(address(this));
        bool ok;
        try c.setKeeper(newKeeper) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok && c.keeper() == newKeeper, "owner-gated setKeeper must succeed and set keeper");
