pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
        // initialize via low-level call to avoid interface-type identity issues
        (bool ok, ) = address(c).call(
            abi.encodeWithSelector(
                C.initialize.selector,
                address(1), // _sGlp
                address(2), // _usdc
                address(3), // _rewardRouter
                address(new GlpManagerMock()), // _glpManager
                address(5), // _dnGmxJuniorVault
                address(6)  // _keeper
            )
        );
        assertTrue(ok, "initialize failed");
    }

    function testFuzz_property(address newOwnerA, address newOwnerB) public {
        // 1. step 1: owner (the deployer, this test contract) transfers ownership to a fuzzed address
        vm.prank(address(this));
        try c.transferOwnership(newOwnerA) {
            // succeeded; ownership is now newOwnerA (or address(0) in the buggy version)
        } catch {
            // P rejects zero-address here; ownership stays with the deployer
        }

        // 2. a call from address(0) must NEVER succeed: the owner is never address(0) in P
        vm.prank(address(0));
        bool ok;
        try c.transferOwnership(newOwnerB) {
            ok = true;
        } catch {
            ok = false;
        }

        // 3. universal rule: transferring ownership from the zero address always reverts.
        // P: holds for ALL inputs (owner is never address(0)).
        // M: when newOwnerA == address(0), owner becomes address(0) and this call succeeds.
        assertTrue(!ok, "zero address must never be able to transfer ownership");
    }
}

