            IERC20(makeAddr("usdc")),
            IRewardRouterV2(makeAddr("rewardRouter")),
            IGlpManager(glpManagerAddr),
            makeAddr("juniorVault"),
            makeAddr("keeper0")
        );
    }

    function testFuzz_property(address newOwner, address newKeeper) public {
        vm.assume(newOwner != address(0));
        // owner transfers ownership to the fuzzed newOwner
        vm.prank(c.owner());
        c.transferOwnership(newOwner);
        // general rule: the new owner (not address(0)) can perform owner-only actions
        bool ok;
        vm.prank(newOwner);
        try c.setKeeper(newKeeper) {
            ok = (c.keeper() == newKeeper);
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

